def lps(str):
    '''Return the length of the longest palindromic subsequence of the input.'''
    s = str
    if not s:
        return 0

    n = len(s)
    dp = [0] * n
    for i in range(n - 1, -1, -1):
        dp[i] = 1
        diagonal = 0
        for j in range(i + 1, n):
