import solution


def _brute_force_lps(text):
    best = 0
    for mask in range(1 << len(text)):
        subsequence = [character for index, character in enumerate(text) if mask & (1 << index)]
        if subsequence == subsequence[::-1] and len(subsequence) > best:
            best = len(subsequence)
    return best


def test_module_imports():
