def test_empty_and_single_character():
    assert solution.lps('') == 0
    assert solution.lps('a') == 1


def test_whole_string_is_palindrome():
    assert solution.lps('racecar') == 7
    assert solution.lps('aabaa') == 5


def test_repeated_characters():
    assert solution.lps('bbbab') == 4
    assert solution.lps('aaaa') == 4


def test_no_repeated_characters():
